function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'TreeAncestor' || !Array.isArray(args[0]) || args[0].length !== 2) return 'Start with TreeAncestor(n, parent).';
  const [n, parent] = args[0];
  if (!Number.isInteger(n) || n < 1 || n > 50000) return 'n is a whole number from 1 to 5 * 10^4.';
  if (!Array.isArray(parent) || parent.length !== n) return 'parent needs exactly n entries.';
  if (parent[0] !== -1) return 'parent[0] must be -1: node 0 is the root.';
  for (let i = 1; i < n; i++) {
    if (!Number.isInteger(parent[i]) || parent[i] < 0 || parent[i] >= n) return 'Every other parent[i] is a node label from 0 to n - 1.';
  }
  // 0 = unseen, 1 = on the current upward walk, 2 = known to reach the root.
  const state = new Array(n).fill(0);
  state[0] = 2;
  for (let start = 1; start < n; start++) {
    const path = [];
    let v = start;
    while (state[v] === 0) { state[v] = 1; path.push(v); v = parent[v]; }
    if (state[v] === 1) return 'parent must form a tree: following parents never reaches node 0 from some node.';
    for (const u of path) state[u] = 2;
  }
  if (operations.length - 1 > 50000) return 'At most 5 * 10^4 queries.';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'getKthAncestor') return 'Only getKthAncestor can follow the constructor.';
    const a = args[i];
    if (!Array.isArray(a) || a.length !== 2) return 'getKthAncestor takes node and k.';
    if (!Number.isInteger(a[0]) || a[0] < 0 || a[0] >= n) return 'node is a label from 0 to n - 1.';
    if (!Number.isInteger(a[1]) || a[1] < 1 || a[1] > n) return 'k is a whole number from 1 to n.';
  }
  return null;
}

