class TreeAncestor {
  constructor(n, parent) {
    let levels = 1;
    while ((1 << levels) <= n) levels++;
    this.up = [parent.slice()];
    for (let j = 1; j < levels; j++) {
      const prev = this.up[j - 1];
      const next = new Array(n);
      for (let v = 0; v < n; v++) {
        next[v] = prev[v] === -1 ? -1 : prev[prev[v]];
      }
      this.up.push(next);
    }
  }

  getKthAncestor(node, k) {
    for (let j = 0; j < this.up.length && node !== -1; j++) {
      if ((k >> j) & 1) {
        node = this.up[j][node];
      }
    }
    return node;
  }
}

