class TreeAncestor {
  constructor(n, parent) {
    this.parent = parent.slice();
  }
  getKthAncestor(node, k) {
    let current = node;
    for (let step = 0; step < k; step++) {
      if (current === -1) return -1;
      current = this.parent[current];
    }
    return current;
  }
}

