function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? 2000 : int(1, 8);
  const order = [0];
  const rest = Array.from({ length: n - 1 }, (_, i) => i + 1);
  for (let i = rest.length - 1; i > 0; i--) { const j = int(0, i); [rest[i], rest[j]] = [rest[j], rest[i]]; }
  order.push(...rest);
  const shape = int(0, 3);
  const parent = new Array(n).fill(-1);
  const depth = new Array(n).fill(0);
  for (let p = 1; p < n; p++) {
    let q;
    if (shape === 0) q = p - 1;
    else if (shape === 1) q = Math.max(0, p - int(1, 3));
    else if (shape === 2) q = int(0, p - 1);
    else q = rand() < 0.5 ? 0 : int(0, p - 1);
    parent[order[p]] = order[q];
    depth[order[p]] = depth[order[q]] + 1;
  }
  const calls = large ? 499 : int(1, 10);
  const operations = ['TreeAncestor'];
  const args = [[n, parent]];
  for (let i = 0; i < calls; i++) {
    const node = int(0, n - 1);
    const roll = rand();
    let k;
    if (roll < 0.6) k = Math.min(n, int(1, depth[node] + 1));
    else if (roll < 0.75) k = Math.min(n, Math.max(1, depth[node]));
    else k = int(1, n);
    operations.push('getKthAncestor');
    args.push([node, k]);
  }
  return [operations, args];
}
